package com.autoops.workflow.validation;import com.autoops.workflow.entity.WorkflowStep;import org.springframework.stereotype.Service;import java.util.*;@Service public class WorkflowGraphValidator{public void validate(List<WorkflowStep> steps){if(steps.isEmpty())throw new IllegalArgumentException("Workflow requires a step");Set<Long>ids=new HashSet<>();steps.forEach(s->{if(s.getId()!=null)ids.add(s.getId());});for(var s:steps){Long a=s.getSuccessNextStepId(),b=s.getFailureNextStepId();if(a!=null&&!ids.contains(a)||b!=null&&!ids.contains(b))throw new IllegalArgumentException("Edge points outside workflow");}detectCycles(steps);}private void detectCycles(List<WorkflowStep>s){Map<Long,WorkflowStep>m=new HashMap<>();s.forEach(x->{if(x.getId()!=null)m.put(x.getId(),x);});Set<Long>v=new HashSet<>(),st=new HashSet<>();for(Long id:m.keySet())dfs(id,m,v,st);}private void dfs(Long id,Map<Long,WorkflowStep>m,Set<Long>v,Set<Long>st){if(st.contains(id))throw new IllegalArgumentException("Workflow cycles are not allowed");if(!v.add(id))return;st.add(id);var x=m.get(id);if(x!=null){if(x.getSuccessNextStepId()!=null)dfs(x.getSuccessNextStepId(),m,v,st);if(x.getFailureNextStepId()!=null)dfs(x.getFailureNextStepId(),m,v,st);}st.remove(id);}}
